      # Binary search for `cp` in a sorted table of [start, end, ...]
      # rows. Returns the matching row or nil.
      def self.lookup(table, cp)
        lo = 0
        hi = table.length - 1
        while lo <= hi
          mid = (lo + hi) / 2
          row = table[mid]
          if cp < row[0]
            hi = mid - 1
          elsif cp > row[1]
            lo = mid + 1
          else
            return row
          end
        end

        nil
      end
    end
